def fracPart' (x : ℝ) : ℝ := Int.fract x

/-- Nyman-Beurling basis: f_k(x) = {k/x} for x ∈ (0,1] -/
def nbBasis' (k : ℕ) (x : ℝ) : ℝ := Int.fract ((k : ℝ) / x)

def liouvilleFunction (n : ℕ) : ℤ :=
  (-1) ^ (n.factorization.sum (fun _ e => e))

-- ── LIOUVILLE PARITY DECOMPOSITION (PT-Symmetry, discovered 2026-04-01) ──

def finiteInterference (fp : FiniteProblem) : ℝ :=
  let s := Finset.univ.sum fp.alpha
  let s2 := Finset.univ.sum (fun m => fp.alpha m ^ 2)
  (1/4) * (s^2 - s2)

def intToOctonion (k : ℕ) : Octonion :=
  if k ≤ 1 then 1
  else Octonion.basis (primeToBasis k.minFac)

/-- Normalization helper: normSq of a basis octonion is 1.

def nbLinComb (N : ℕ) (w : Fin (N - 1) → ℝ) (x : ℝ) : ℝ :=
  ∑ i : Fin (N - 1), w i * Int.fract ((↑(i.val + 1) : ℝ) / x)

